static int fill_write_buffer(struct configfs_buffer *buffer,
			     struct iov_iter *from)
{
	int copied;

	if (!buffer->page)
		buffer->page = (char *)__get_free_pages(GFP_KERNEL, 0);
	if (!buffer->page)
		return -ENOMEM;

	copied = copy_from_iter(buffer->page, SIMPLE_ATTR_SIZE - 1, from);
